    """True if the schedule expr runs at the minute of the datetime when."""
    spec = _parse(expr)
    if when.month not in spec.months:
        return False
    if when.hour * 60 + when.minute not in spec.minutes_of_day:
        return False
    last = calendar.monthrange(when.year, when.month)[1]
    return _day_matches(spec, when.date(), last)


def next_run(expr, after):
    """The first run of expr strictly after the datetime after, or None."""
    spec = _parse(expr)
    try:
        first = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
        limit = after + timedelta(days=50 * 365)
    except OverflowError:
        return None
    times = spec.minutes_of_day
    first_day = first.date()
    year, month = first.year, first.month
    while (year, month) <= (limit.year, limit.month):
        if month in spec.months:
            last = calendar.monthrange(year, month)[1]
            for d in range(1, last + 1):
                day = date(year, month, d)
                if day < first_day or not _day_matches(spec, day, last):
                    continue
                start_t = first.hour * 60 + first.minute if day == first_day else 0
                i = bisect.bisect_left(times, start_t)
                if i == len(times):
                    continue
                t = times[i]
                candidate = first.replace(year=year, month=month, day=d,
                                          hour=t // 60, minute=t % 60)
                if candidate > limit:
                    return None
                return candidate
        month += 1
        if month == 13:
            month = 1
            year += 1
    return None
